module tb_TopModule;
  logic a, b, cin;
  logic cout, sum;

  TopModule uut (
    .a(a),
    .b(b),
    .cin(cin),
    .cout(cout),
    .sum(sum)
  );

  initial begin
    integer i;
    reg [2:0] expected;
    reg [1:0] actual;

    for (i = 0; i < 8; i = i + 1) begin
      {a, b, cin} = i[2:0];
      #10;
      expected = a + b + cin;
      actual = {cout, sum};
      if (actual !== expected) begin
        $display("SELFTEST FAIL: a=%b b=%b cin=%b -> got cout=%b sum=%b (actual=%0b), expected cout=%b sum=%b (expected=%0b)",
                 a, b, cin, cout, sum, actual, expected[1], expected[0], expected);
        $finish;
      end
    end

    $display("SELFTEST PASS");
    $finish;
  end
endmodule
